// TOTVS Protheus — obter token Bearer (Node 18+)
const BASE = process.env.PROTHEUS_BASE_URL!.replace(/\/+$/, ""); // https://<<SEU_SERVIDOR>>:<<PORTA>>/rest

export async function obterToken() {
  const r = await fetch(`${BASE}/api/oauth2/v1/token?grant_type=password`, {
    method: "POST",
    headers: {
      username: process.env.PROTHEUS_USUARIO!, // <<SEU_USUARIO_PROTHEUS>>
      password: process.env.PROTHEUS_SENHA!,   // <<SUA_SENHA_PROTHEUS>>
      Accept: "application/json",
    },
  });
  if (!r.ok) throw new Error(`Token recusado (HTTP ${r.status}): ${(await r.text()).slice(0, 300)}`);
  const d: any = await r.json();
  return { accessToken: d.access_token as string, refreshToken: d.refresh_token as string, expiraEm: d.expires_in ?? 3600 };
}

obterToken().then((t) => console.log(`token obtido; expira em ${t.expiraEm} s`));

// TOTVS Protheus — renovar token com refresh_token (Node 18+)
const BASE = process.env.PROTHEUS_BASE_URL!.replace(/\/+$/, "");

export async function renovar(refreshToken: string) {
  const qs = new URLSearchParams({ grant_type: "refresh_token", refresh_token: refreshToken });
  const r = await fetch(`${BASE}/api/oauth2/v1/token?${qs}`, { method: "POST", headers: { Accept: "application/json" } });
  if (!r.ok) throw new Error(`Renovação recusada (HTTP ${r.status}); refaça o login com usuário e senha.`);
  const d: any = await r.json();
  return { accessToken: d.access_token as string, refreshToken: d.refresh_token as string };
}

