import base64
import os
import time

import requests

# TOTVS Protheus — leitura pela API genericQuery (somente leitura).
# Endereço e credenciais vêm de variáveis de ambiente, nunca fixos no código.
BASE = os.environ["PROTHEUS_BASE_URL"].rstrip("/")  # ex.: https://<<SEU_SERVIDOR>>:<<PORTA>>/rest
USUARIO = os.environ["PROTHEUS_USUARIO"]            # <<SEU_USUARIO_PROTHEUS>> (usuário dedicado à integração)
SENHA = os.environ["PROTHEUS_SENHA"]                # <<SUA_SENHA_PROTHEUS>>
TENANT = os.environ["PROTHEUS_TENANT_ID"]           # <<GRUPO_EMPRESAS>>,<<FILIAL>>

BASIC = base64.b64encode(f"{USUARIO}:{SENHA}".encode()).decode()
HEADERS = {"Authorization": f"Basic {BASIC}", "tenantId": TENANT, "Accept": "application/json"}


def generic_query(params, tamanho=100):
    """Lê todas as páginas (page/pagesize) até hasNext vir false."""
    registros, pagina = [], 1
    while True:
        consulta = {**params, "page": pagina, "pagesize": tamanho}
        for tentativa in range(3):
            r = requests.get(f"{BASE}/api/framework/v1/genericQuery", params=consulta, headers=HEADERS, timeout=120)
            if r.status_code in (502, 503, 504) and tentativa < 2:
                time.sleep(10 * (tentativa + 1))  # 503: nenhuma licença livre no License Server
                continue
            break
        if r.status_code == 401:
            raise RuntimeError("401: confira usuário/senha e se o usuário tem acesso à filial do tenantId.")
        if r.status_code >= 400:
            raise RuntimeError(f"Protheus respondeu HTTP {r.status_code}: {r.text[:300]}")
        corpo = r.json()
        registros.extend(corpo.get("items", []))
        if corpo.get("protectedDataFields"):
            print("Campos ocultados (dados protegidos):", corpo["protectedDataFields"])
        if not corpo.get("hasNext"):
            return registros
        pagina += 1


if __name__ == "__main__":
    linhas = generic_query({
        "tables": "SE1",
        "fields": "e1_filial,e1_prefixo,e1_num,e1_parcela,e1_tipo,e1_cliente,e1_loja,e1_naturez,e1_emissao,e1_vencto,e1_vencrea,e1_valor,e1_saldo,e1_baixa,e1_portado,e1_situaca,e1_vend1,e1_hist",
        "where": "E1_VENCREA >= '20260801' AND E1_VENCREA <= '20260831'",
    })
    print(len(linhas), "registros")

