// TOTVS Protheus — leitura pela API genericQuery (Node 18+, fetch nativo). Somente leitura.
const BASE = process.env.PROTHEUS_BASE_URL!.replace(/\/+$/, ""); // https://<<SEU_SERVIDOR>>:<<PORTA>>/rest
const USUARIO = process.env.PROTHEUS_USUARIO!;   // <<SEU_USUARIO_PROTHEUS>>
const SENHA = process.env.PROTHEUS_SENHA!;       // <<SUA_SENHA_PROTHEUS>>
const TENANT = process.env.PROTHEUS_TENANT_ID!;  // <<GRUPO_EMPRESAS>>,<<FILIAL>>
const HEADERS = {
  Authorization: "Basic " + Buffer.from(`${USUARIO}:${SENHA}`).toString("base64"),
  tenantId: TENANT,
  Accept: "application/json",
};
const espera = (s: number) => new Promise((r) => setTimeout(r, s * 1000));

async function genericQuery(params: Record<string, string>, tamanho = 100): Promise<any[]> {
  const registros: any[] = [];
  for (let pagina = 1; ; pagina++) {
    const qs = new URLSearchParams({ ...params, page: String(pagina), pagesize: String(tamanho) });
    let r: Response | undefined;
    for (let t = 0; t < 3; t++) {
      r = await fetch(`${BASE}/api/framework/v1/genericQuery?${qs}`, { headers: HEADERS });
      if (![502, 503, 504].includes(r.status)) break;
      await espera(10 * (t + 1)); // 503: sem licença livre no License Server
    }
    if (r!.status === 401) throw new Error("401: confira usuário/senha e o acesso do usuário à filial do tenantId.");
    if (!r!.ok) throw new Error(`Protheus respondeu HTTP ${r!.status}: ${(await r!.text()).slice(0, 300)}`);
    const corpo: any = await r!.json();
    registros.push(...(corpo.items ?? []));
    if (!corpo.hasNext) return registros;
  }
}

genericQuery({
  tables: "SE1",
  fields: "e1_num,e1_parcela,e1_cliente,e1_vencrea,e1_saldo",
  where: "E1_SALDO > 0 AND E1_VENCREA < '20260801'",
}).then((l) => console.log(`${l.length} registros`));
